"""Documentation that must track the code: the generated graph topology and the mirrored agent guides."""
from pathlib import Path

from langgraph.checkpoint.memory import MemorySaver

from app import workflow

ROOT = Path(__file__).resolve().parent.parent


def test_committed_graph_diagram_matches_the_compiled_graph():
    """docs/architecture.mmd is generated by `make graph`; a changed edge without re-export fails here."""
    generated = workflow.compile(checkpointer=MemorySaver()).get_graph().draw_mermaid()
    committed = (ROOT / "docs" / "architecture.mmd").read_text(encoding="utf-8")
    assert committed == generated, "docs/architecture.mmd is stale: run 'make graph' and commit the result"


def test_every_graph_node_appears_in_the_hand_drawn_diagrams():
    nodes = {n for n in workflow.compile(checkpointer=MemorySaver()).get_graph().nodes if not n.startswith("__")}
    for doc in ("CLAUDE.md", "README.md"):
        text = (ROOT / doc).read_text(encoding="utf-8")
        missing = sorted(n for n in nodes if f"[{n}]" not in text)
        assert not missing, f"{doc} diagram is missing nodes: {missing}"


def test_agent_guides_are_byte_identical():
    """CLAUDE.md is the source; AGENTS.md mirrors it for other coding agents."""
    assert (ROOT / "CLAUDE.md").read_bytes() == (ROOT / "AGENTS.md").read_bytes(), "copy CLAUDE.md over AGENTS.md"
